var t=[{title:`Ralentissez progressivement`,text:`Après une course ou une sortie à vélo intense, marchez ou pédalez doucement quelques minutes au lieu de vous arrêter net à pleine intensité. Après le travail de force, une courte marche détendue et une respiration normale peuvent faire du bien. S’arrêter brusquement peut parfois donner des étourdissements, surtout après une activité longue et intense.`},{title:`Mobilité douce facultative`,text:`Vous pouvez ajouter des mouvements confortables pour les mollets, les hanches, la poitrine ou les épaules si la souplesse fait partie de vos objectifs ou si vous les appréciez simplement. Visez une légère sensation d’étirement et ne forcez pas de grandes amplitudes. Les étirements profonds juste après une séance fatigante sont facultatifs, et les étirements douloureux vous desservent.`},{title:`Ce que montrent les données`,text:`Un mouvement léger peut rendre les premières minutes après la séance plus confortables. Il existe peu de données montrant qu’un retour au calme ou une routine d’étirements standard prévient de façon fiable les courbatures du lendemain (DOMS). La progression graduelle, le sommeil et la récupération comptent toujours. Un retour au calme ne soigne pas une blessure et ne remplace pas les soins médicaux.`},{title:`Adapter à la séance`,text:`Une marche modérée peut se terminer par une ou deux minutes faciles. Après une séance d’intervalles difficile, prenez plusieurs minutes de mouvement facile et de respiration jusqu’à vous sentir stable. Si des étourdissements, un essoufflement inhabituel, une douleur à la poitrine ou un malaise ne passent pas, arrêtez de vous entraîner et demandez une aide médicale.`}];var n=[{label:`NHS : exercice doux de retour au calme`,url:`https://www.nhs.uk/live-well/exercise/strength-and-resistance/body-blast-cool-down/`},{label:`ACE 2026 : conseils pratiques sur les étirements`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`NHS : courbatures musculaires d’apparition retardée`,url:`https://www.leicspart.nhs.uk/msk-physiotherapy-resources-getting-started/msk-physiotherapy-resources-faqs/`}];var r={sections:t,sources:n};export{r as default,t as sections,n as sources};